	-- plural, as words: Eldreth Seethers = {npc:11469} Eldreth Seether · Dark Runes = {item:20520} Dark Rune · Large Brilliant Shards = {item:14344} Large Brilliant Shard
	["{npc:16032} wants a {item:22224} (the Eldreth ghosts of Dire Maul West, best the Eldreth Seethers, and the invisible spectres around {npc:11496}'s prison), 4 Dark Runes (the necromancers and summoners of {area:2057}, whose gate opens to a {item:13704}: one in the group is enough; or the auction house) and 8 Large Brilliant Shards (enchanters, or the auction house)."] = "{npc:16032} 需要一个 {item:22224}（厄运之槌西区的艾德雷斯幽灵掉落，最好打艾德雷斯怨魂，以及 {npc:11496} 牢笼周围的隐形幽灵），4 个黑暗符文（{area:2057} 的通灵师和召唤师掉落，其大门需用 {item:13704} 打开：小队中有一人持有即可；或去拍卖行买）和 8 个大块闪光碎片（找附魔师，或去拍卖行买）。",

	-- Step 29: The Challenge
	-- {npc:16032} Falrin Treeshaper · {item:21986} Banner of Provocation · {area:1584} Blackrock Depths
	-- was: ["{npc:16032} finishes the {item:21986}: plant it in the Ring of Law in {area:1584}."] = "{npc:16032} 会完成 {item:21986}：把它插在 {area:1584} 的秩序竞技场中。"
	["{npc:16032} finishes the {item:21986}, for the Ring of Law in {area:1584}."] = "",

	-- Step 30: Blackrock Depths: the Ring of Law
	-- {area:1584} Blackrock Depths
	["{area:1584}: the Ring of Law"] = "{area:1584}：法律之环",
	-- {area:1584} Blackrock Depths · {area:254} Blackrock Mountain · {zone:1427} Searing Gorge · {zone:1428} Burning Steppes · {npc:10096} High Justice Grimstone · {item:21986} Banner of Provocation · {npc:16059} Theldren · {item:22047} Top Piece of Lord Valthalak's Amulet
	["{area:1584} is the dungeon inside {area:254}, between the {zone:1427} and the {zone:1428}; a group of five. Walk into the Ring of Law so {npc:10096} sentences you, and while he reads the sentence plant the {item:21986} in the middle of the ring. After the first wave, {npc:16059} and his gladiators come instead of the usual boss: five elites who fight like players (crowd control, dispels, no taunts). Kill them all; {npc:16059} drops the {item:22047}."] = "{area:1584} 是位于 {area:254} 内的地下城，处于 {zone:1427} 和 {zone:1428} 之间；需要五人小队。走进法律之环，让 {npc:10096} 对你宣判，在他宣读判决时，把 {item:21986} 插在竞技场中央。第一波之后，出现的不再是常规首领，而是 {npc:16059} 和他的角斗士：五个像玩家一样战斗的精英（控制、驱散，不可嘲讽）。全部击杀；{npc:16059} 会掉落 {item:22047}。",
	-- {item:21986} Banner of Provocation
	["{item:21986}, in the ring"] = "{item:21986}，插在竞技场中",

	-- Step 31: Anthion Harmon: Anthion's Parting Words
	-- {npc:16016} Anthion Harmon · {area:2279} Stratholme · {quest:84180} Anthion's Parting Words · {item:16675} Beaststalker's Boots · {npc:10437} Nerub'enkan · {item:16678} Beaststalker's Pants · {npc:10440} Baron Rivendare · {item:16679} Beaststalker's Mantle · {npc:9568} Overlord Wyrmthalak
	["Back to {npc:16016} at {area:2279}'s gate (Ghost Revealer). {quest:84180} takes your {item:16675}: {npc:10437} in {area:2279} (about 18%), your {item:16678}: {npc:10440} in {area:2279} (about 10%), and your {item:16679}: {npc:9568} in Lower Blackrock Spire (about 17%)."] = "回到{area:2279}大门的{npc:16016}处（幽灵显形器）。{quest:84180}需要你的{item:16675}：{area:2279}的{npc:10437}（约18%），你的{item:16678}：{area:2279}的{npc:10440}（约10%），以及你的{item:16679}：黑石塔下层的{npc:9568}（约17%）。",

	-- Step 34: Bodley
	-- {npc:16033} Bodley · {area:1583} Blackrock Spire · {area:254} Blackrock Mountain · {quest:8961} Three Kings of Flame · {item:21987} Incendicite of Incendius · {npc:9017} Lord Incendius · {area:1584} Blackrock Depths · {item:21988} Ember of Emberseer · {npc:9816} Pyroguard Emberseer · {item:21989} Cinder of Cynders · {npc:15206} Duke of Cynders · {zone:1451} Silithus · {item:22014} Hallowed Brazier · {faction:529} Argent Dawn
	-- was: ["{npc:16033}'s ghost stands on the ledge before the {area:1583} portal, high inside {area:254}: use the Ghost Revealer there. {quest:8961} wants the {item:21987} ({npc:9017} in {area:1584}), the {item:21988} ({npc:9816} in Upper Blackrock Spire), the {item:21989} (the {npc:15206} in {zone:1451}) and a {item:22014} from the {faction:529}."] = "{npc:16033} 的灵魂站在 {area:254} 高处、{area:1583} 传送门前的平台上：在那里使用灵魂显形器。{quest:8961} 需要 {item:21987}（{area:1584} 的 {npc:9017}）、{item:21988}（黑石塔上层的 {npc:9816}）、{item:21989}（{zone:1451} 的 {npc:15206}），以及来自 {faction:529} 的一个 {item:22014}。"
	["{npc:16033}'s ghost stands on the ledge before the {area:1583} portal, high inside {area:254}, and only the Ghost Revealer shows him. {quest:8961} needs the {item:21987} ({npc:9017}, {area:1584}), the {item:21988} ({npc:9816}, Upper Blackrock Spire), the {item:21989} (the {npc:15206}, {zone:1451}) and a {item:22014} from the {faction:529}."] = "",

	-- Step 36: Honored with the Argent Dawn
	-- {faction:529} Argent Dawn
	["Honored with the {faction:529}"] = "{faction:529} 声望达到尊敬",
	-- {item:22014} Hallowed Brazier · {item:12846} Argent Dawn Commission · {area:2279} Stratholme · {area:2057} Scholomance · {area:2268} Light's Hope Chapel
	["The {item:22014} is sold only at Honored. The Scourge drop Scourgestones for the Argent officers only while the {item:12846} is worn. Every Scourge kill in the Plaguelands counts, {area:2279} and {area:2057} undead give 5 each up to Honored, and {area:2268}'s dungeon quests give 100-200 each."] = "",
	-- {item:12846} Argent Dawn Commission
	["{item:12846}, while you fight the Scourge"] = "",

	-- Step 37: Hallowed Brazier
	-- {object:2160} The Argent Dawn · {area:2268} Light's Hope Chapel · {area:3197} Chillwind Camp · {area:813} Bulwark
	["{object:2160} quartermasters ({area:2268}, {area:3197}, the {area:813}) sell it: 133 gold 33 silver, less with your reputation discount."] = "{object:2160} 军需官（{area:2268}、{area:3197}、{area:813}）出售：133 金 33 银，声望折扣后更便宜。",

	-- Step 38: Blackrock Depths and Upper Blackrock Spire
	-- {area:1584} Blackrock Depths
	["{area:1584} and Upper Blackrock Spire"] = "{area:1584}与黑石塔上层",
	-- {npc:9017} Lord Incendius · {object:174825} Black Anvil (no name in this language: may be words) · {area:1584} Blackrock Depths · {npc:9816} Pyroguard Emberseer
	["{npc:9017} guards the {object:174825} in {area:1584} (a group of five). {npc:9816} is the first boss of Upper Blackrock Spire, a group of up to ten. Each player with the quest loots their own."] = "{npc:9017} 守卫着 {area:1584} 中的 {object:174825}（五人小队）。{npc:9816} 是黑石塔上层的第一个首领，最多十人小队。每个有任务的玩家各自拾取。",
	-- {npc:9816} Pyroguard Emberseer
	["{npc:9816}, Upper Blackrock Spire"] = "{npc:9816}，黑石塔上层",

	-- Step 39: Duke of Cynders
	-- {zone:1451} Silithus · {item:20422} Twilight Cultist Medallion of Station · {npc:15282} Aurel Goldleaf · {area:3425} Cenarion Hold · {item:14344} Large Brilliant Shard · {item:20432} Signet of Beckoning: Fire · {npc:15206} Duke of Cynders
	-- plural, as words: Greater Wind Stones = {object:180466} Greater Wind Stone · Abyssal Crests = {item:20513} Abyssal Crest
	["The Duke (level 62 elite, bring a group of five) only comes when someone summons him at one of the Twilight's Greater Wind Stones in {zone:1451}: the summoner wears the full Twilight Cultist set (Cowl, Mantle and Robe, from the Twilight cultists of the {zone:1451} camps), carries a {item:20422} ({npc:15282} at {area:3425}: three Abyssal Crests from summoned Templars and a {item:14344}) and a {item:20432}, which calls the {npc:15206} rather than a random Duke. Joining someone else's summon is the quick way: every player with the quest loots their own Cinder."] = "公爵（62级精英，需五人小队）只有在有人于 {zone:1451} 的暮光大风石召唤时才会出现：召唤者须穿戴整套暮光教徒套装（兜帽、护肩和长袍，来自 {zone:1451} 营地的暮光教徒），携带 {item:20422}（{area:3425} 的 {npc:15282}：需要三枚召唤出的圣殿骑士掉落的深渊纹章和一个 {item:14344}）以及 {item:20432}，后者会召唤 {npc:15206} 而非随机公爵。加入别人的召唤最快：每个有此任务的玩家都能拾取自己的余烬。",

	-- Step 40: Bodley: Components of Importance
	-- {npc:16033} Bodley
	["{npc:16033}'s next task depends on your class: the piece the summoning brazier needs."] = "{npc:16033} 的下一个任务取决于你的职业：召唤火盆所需的那件物品。",

	-- Step 42: Components of Importance: Brilliant Sword of Zealotry
	-- {area:2266} Tyr's Hand · {zone:1423} Eastern Plaguelands · {item:22228} Brilliant Sword of Zealotry
	-- plural, as words: Scarlet Praetorians = {npc:9448} Scarlet Praetorian
	["At {area:2266}, the Scarlet town in the south-east of the {zone:1423}, the Scarlet Praetorians (level 56-57 elites) of its upper courtyard drop the {item:22228} (a rare drop: up to about 50 kills). They are elites: bring a friend or two unless your gear is good. It drops only while you have the quest; everyone in the group with it can loot one."] = "在{zone:1423}东南部的血色城镇{area:2266}，上层庭院的血色禁卫队（56-57级精英）会掉落{item:22228}（稀有掉落：最多约50只）。它们是精英：除非装备够好，带一两个朋友。只有接了任务才会掉落；小队中有该任务的每个人都能拾取一个。",

	-- Step 44: The Left Piece of Lord Valthalak's Amulet
	-- {npc:16033} Bodley · {item:22051} Brazier of Beckoning
	["{npc:16033} gives you a {item:22051}."] = "{npc:16033} 给你一个 {item:22051}。",

	-- Step 45: The Left Piece of Lord Valthalak's Amulet: Jarien and Sothos
	-- {quest:8968} The Left Piece of Lord Valthalak's Amulet · {npc:16101} Jarien · {npc:16102} Sothos
	["{quest:8968}: {npc:16101} and {npc:16102}"] = "{quest:8968}：{npc:16101} 和 {npc:16102}",
	-- {npc:16033} Bodley · {item:22051} Brazier of Beckoning · {npc:16101} Jarien · {npc:16102} Sothos · {area:2279} Stratholme
	["A dungeon run for a group of five. {npc:16033}'s {item:22051} calls {npc:16101} and {npc:16102} to Balnazzar's chamber at the end of {area:2279}'s Scarlet side, through the main gate: clear to it first. Use the brazier there, kill {npc:16101} and {npc:16102} and loot the piece. Both are elites: {npc:16101} cleaves, so tank him facing away; {npc:16102} fears. When one falls the other's spirit fights on. Keep the brazier: {npc:16033} wants it back with the piece."] = "需要五人小队进入地下城。{npc:16033}的{item:22051}可将{npc:16101}和{npc:16102}召唤到{area:2279}血色区（从正门进入）尽头的巴纳扎尔房间：先清到那里。使用那里的火盆，击杀{npc:16101}和{npc:16102}并拾取碎片。两者都是精英：{npc:16101}会顺劈，坦克要让他背对队伍；{npc:16102}会恐惧。其中一个倒下后，另一个的灵魂会继续战斗。保留火盆：{npc:16033}要你连同碎片一起交回。",
	-- {item:22051} Brazier of Beckoning · {npc:16101} Jarien · {npc:16102} Sothos
	["{item:22051}: summons {npc:16101} and {npc:16102}"] = "{item:22051}：召唤{npc:16101}和{npc:16102}",

	-- Step 48: Bloodkelp
	-- {area:2079} Alcaz Island · {zone:1445} Dustwallow Marsh · {npc:16072} Tidelord Rrurgaz
	["The Strashaz naga of {area:2079}, off the north-east coast of {zone:1445}, carry it (level 59-61 elites, and {npc:16072} at 62): bring a friend or two. The Baskets of Bloodkelp on the island give 1 to 3 each without a fight. Swim over from the coast north of Theramore; elite hydras roam the water."] = "{zone:1445} 东北海岸外 {area:2079} 的斯拉莎兹纳迦身上带有它（59-61级精英，{npc:16072} 为62级）：带一两个朋友。岛上的血藻篮无需战斗，每个给1到3个。从塞拉摩以北的海岸游过去；水中有游荡的精英九头蛇。",

	-- Step 51: More Components of Importance: Soul Ashes of the Banished
	-- {area:896} Purgation Isle · {zone:1424} Hillsbrad Foothills · {item:22229} Soul Ashes of the Banished
	["At {area:896}, the island off the south coast of the {zone:1424}, the Condemned and Cursed undead (level 57-60 elites), thickest by the tower on the hill drop the {item:22229} (usually 5 to 15 kills; they stun, so a healer or dispeller helps). They are elites: bring a friend or two unless your gear is good. It drops only while you have the quest; everyone in the group with it can loot one."] = "在{zone:1424}南部海岸外的岛屿{area:896}，被诅咒和受诅的亡灵（57-60级精英）在山上塔楼附近最密集，会掉落{item:22229}（通常5到15只；它们会击晕，有治疗或驱散会更轻松）。它们是精英：除非装备够好，带一两个朋友。只有接了任务才会掉落；小队中有该任务的每个人都能拾取一个。",

	-- Step 54: The Right Piece of Lord Valthalak's Amulet: Kormok
	-- {npc:16033} Bodley · {item:22052} Brazier of Beckoning · {npc:16118} Kormok · {npc:10508} Ras Frostwhisper · {area:2057} Scholomance · {spell:27688} Bone Shield · {item:21984} Left Piece of Lord Valthalak's Amulet · {item:22048} Lord Valthalak's Amulet
	["A dungeon run for a group of five. {npc:16033}'s {item:22052} calls {npc:16118} to {npc:10508}'s room in {area:2057}: clear the room first. Use the brazier there, kill {npc:16118} and loot the piece. He is an elite ogre spirit who keeps raising skeletons: dispel or purge his {spell:27688} and burn him down. After a wipe he stays up: come back without summoning again. Keep the brazier: {npc:16033} wants it back with the piece. Then use the {item:21984} ({npc:16033} gave it back to you) to join the pieces into {item:22048}."] = "需要五人小队进入地下城。{npc:16033}的{item:22052}可将{npc:16118}召唤到{area:2057}中{npc:10508}的房间：先清理房间。使用那里的火盆，击杀{npc:16118}并拾取碎片。他是精英食人魔灵魂，会不断召唤骷髅：驱散或净化他的{spell:27688}，集中火力击杀他。团灭后他会留在原地：回来时无需再次召唤。保留火盆：{npc:16033}要你连同碎片一起交回。然后使用{item:21984}（{npc:16033}已还给你）将碎片合成{item:22048}。",
	-- {item:22052} Brazier of Beckoning · {npc:16118} Kormok
	["{item:22052}: summons {npc:16118}"] = "{item:22052}：召唤{npc:16118}",
	-- {item:21984} Left Piece of Lord Valthalak's Amulet
	["{item:21984}: joins the pieces"] = "{item:21984}：合并碎片",

	-- Step 56: Final Preparations
	-- {area:1583} Blackrock Spire · {item:13512} Flask of Supreme Power
	-- plural, as words: Blackrock Bracers = {item:22138} Blackrock Bracer · Scarshield Grunts = {npc:9043} Scarshield Grunt
	["40 Blackrock Bracers from the Blackrock orcs of {area:1583} (the Scarshield Grunts in the mountain's halls outside the portal, level 53-54 elites, drop them most often; Upper {area:1583}'s orcs better than Lower's), only while you have the quest, and a {item:13512} (alchemists make it at an alchemy lab; or the auction house)."] = "从{area:1583}的黑石兽人身上收集40个黑石护腕（传送门外山体大厅里的裂盾步兵，53-54级精英，掉率最高；上层{area:1583}的兽人掉率高于下层），只有接了任务才会掉落；另需一个{item:13512}（炼金师在炼金实验室制作，或从拍卖行购买）。",

	-- Step 58: Upper Blackrock Spire: Lord Valthalak
	-- {area:1583} Blackrock Spire · {npc:16042} Lord Valthalak
	["Upper {area:1583}: {npc:16042}"] = "{area:1583}上层：{npc:16042}",
	-- {npc:10430} The Beast · {item:22056} Brazier of Beckoning · {npc:16042} Lord Valthalak · {item:22048} Lord Valthalak's Amulet · {quest:8996} Return to Bodley
	["A raid of up to ten in Upper Blackrock Spire. Clear to {npc:10430}'s room and kill {npc:10430}, then use the {item:22056} there to call {npc:16042} (level 63 boss). Kill his shades quickly; in his last phase he hits the whole room hard. Use {item:22048} on his corpse: his spirit appears. Give him the amulet, then take {quest:8996} from him."] = "黑石塔上层，最多十人的团队。清到{npc:10430}的房间并击杀{npc:10430}，然后在那里使用{item:22056}召唤{npc:16042}（63级首领）。迅速击杀他的暗影；最后阶段他会对整个房间造成重创。对他的尸体使用{item:22048}：他的灵魂会出现。把护符交给他，然后从他那里接受{quest:8996}。",
	-- {item:22056} Brazier of Beckoning · {npc:10430} The Beast
	["{item:22056}, in {npc:10430}'s room"] = "{item:22056}，在{npc:10430}的房间",
	-- {item:22048} Lord Valthalak's Amulet
	["{item:22048}, on his corpse"] = "{item:22048}，用在他的尸体上",

	-- Step 59: Bodley: Back to the Beginning
	-- {npc:16033} Bodley · {item:22056} Brazier of Beckoning
	["Hand {npc:16033} the {item:22056}."] = "把 {item:22056} 交给 {npc:16033}。",

	-- Step 60: Deliana: Saving the Best for Last
	-- {quest:84196} Saving the Best for Last · {item:16677} Beaststalker's Cap · {npc:1853} Darkmaster Gandling · {area:2057} Scholomance · {item:16674} Beaststalker's Tunic · {npc:10363} General Drakkisath
	["{quest:84196} takes your {item:16677}: {npc:1853} in {area:2057} (about 13%), and your {item:16674}: {npc:10363} in Upper Blackrock Spire (about 11%)."] = "{quest:84196} 需要你的 {item:16677}：{area:2057} 的 {npc:1853} 掉落（约 13%），以及你的 {item:16674}：黑石塔上层的 {npc:10363} 掉落（约 11%）。",

	-- Step 61: Mokvar: Saving the Best for Last
	-- {quest:84204} Saving the Best for Last · {item:16677} Beaststalker's Cap · {npc:1853} Darkmaster Gandling · {area:2057} Scholomance · {item:16674} Beaststalker's Tunic · {npc:10363} General Drakkisath
	["{quest:84204} takes your {item:16677}: {npc:1853} in {area:2057} (about 13%), and your {item:16674}: {npc:10363} in Upper Blackrock Spire (about 11%)."] = "{quest:84204} 需要你的 {item:16677}：{area:2057} 的 {npc:1853} 掉落（约 13%），以及你的 {item:16674}：黑石塔上层的 {npc:10363} 掉落（约 11%）。",

	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["Polestar's quest data doesn't know Forever's {quest:84196} for the {npc:235049} yet, so this guide can't track it: {npc:230317} should offer it now. Take it from him and give him your {item:16677} and {item:16674}."] = "北极星的任务数据还不认识无限服中 {npc:235049} 的 {quest:84196}，所以本指南无法追踪：{npc:230317} 现在应该会提供该任务。从他那里接受，并把你的 {item:16677} 和 {item:16674} 交给他。",
	-- ["The Tortured Druids and Sentinels haunt {area:2738} in {zone:1451} (level 55-57, not elite; silithid can join when they die). Place the {item:21946} among the ghosts, pull them into its glow and kill them there, standing in it yourself: ectoplasm only drops from a ghost that dies inside the glow. It lasts a few minutes, then place it again."] = "被折磨的德鲁伊和哨兵徘徊在 {zone:1451} 的 {area:2738}（55-57级，非精英；它们死亡时可能会有异种虫加入）。把 {item:21946} 放在鬼魂之间，把它们拉进光晕里击杀，你自己也站在光晕中：只有死在光晕内的鬼魂才会掉落灵质。它持续几分钟，之后再放置一次。",
	-- ["The ghosts and banshees of the {zone:1423} (Unseen Servants, Eyeless Watchers, Death Singers, Hate Shriekers; level 55-59, not elite) drop it; {area:2272} in the north-east is a good spot. The shriekers fear: fight close to the distiller. Place the {item:21946} among the ghosts, pull them into its glow and kill them there, standing in it yourself: ectoplasm only drops from a ghost that dies inside the glow. It lasts a few minutes, then place it again."] = "{zone:1423} 的鬼魂和女妖（无影仆从、无眼观察者、死亡歌手、憎恨吟唱者；55-59级，非精英）会掉落它；东北部的 {area:2272} 是个好地点。憎恨吟唱者会恐惧：靠近蒸馏器作战。把 {item:21946} 放在鬼魂之间，把它们拉进光晕里击杀，你自己也站在光晕中：只有死在光晕内的鬼魂才会掉落灵质。它持续几分钟，之后再放置一次。",
	-- ["The {item:22014} is sold only to Honored. Take the {item:12846} ({npc:10840} at {area:3197}, {npc:10839} at the {area:813}, or {npc:11039} at {area:2268}) and wear it: Scourgestones then drop from the Scourge, and the Argent officers take them back for reputation. Every Scourge kill in the Plaguelands counts, {area:2279}'s and {area:2057}'s undead give 5 each up to Honored, and {area:2268}'s dungeon quests give 100-200 each. Polestar's Argent Dawn Reputation guide (Reputation) walks it step by step."] = "{item:22014} 只卖给尊敬声望的玩家。领取 {item:12846}（{area:3197} 的 {npc:10840}、{area:813} 的 {npc:10839}，或 {area:2268} 的 {npc:11039}）并装备它：之后天灾军团会掉落天灾石，银色黎明的军官会回收它们并给予声望。在瘟疫之地击杀任何天灾怪物都算数，{area:2279} 和 {area:2057} 的亡灵每只给5点，直到尊敬，{area:2268} 的地下城任务每个给100-200点。Polestar 的银色黎明声望指南（声望）会一步步带你完成。",
	-- ["The {spell:17735} and {npc:7524} drift around {area:2251} in {zone:1452} (level 54-56, not elite). Place the {item:21946} among the ghosts, pull them into its glow and kill them there, standing in it yourself: ectoplasm only drops from a ghost that dies inside the glow. It lasts a few minutes, then place it again. While you are in {zone:1452}, buy the {item:21939} (40 gold) from {npc:16015}, an imp in the cave at the mouth of {area:2256} in the far south: keep to the right-hand wall to slip past the elite demons in the gorge. {quest:8928} asks for it later, and this saves the trip back."] = "{spell:17735} 和 {npc:7524} 在 {zone:1452} 的 {area:2251} 一带游荡（54-56级，非精英）。把 {item:21946} 放在鬼魂中间，将它们拉进光芒范围内击杀，你自己也要站在光芒里：只有在光芒中死亡的鬼魂才会掉落灵质。它持续几分钟，到时再放一次。在 {zone:1452} 期间，顺便从 {npc:16015} 处购买 {item:21939}（40金），他是一只小鬼，位于最南端 {area:2256} 入口处的洞穴里：沿右侧岩壁走，可以绕过峡谷中的精英恶魔。{quest:8928} 稍后会需要它，这样可以省去往返一趟。",
	-- ["{npc:16016}'s ghost waits on the bridge before {area:2279}'s main gate, at the north end of the {zone:1423}. Use the {item:22115} there to see him."] = "{npc:16016} 的鬼魂在 {zone:1423} 北端、{area:2279} 正门前的桥上等你。在那里使用 {item:22115} 才能看见他。",
	-- ["{npc:16032} finishes the {item:21986}: plant it in the Ring of Law in {area:1584}."] = "{npc:16032} 会完成 {item:21986}：把它插在 {area:1584} 的秩序竞技场中。",
	-- ["{npc:16033}'s ghost stands on the ledge before the {area:1583} portal, high inside {area:254}: use the Ghost Revealer there. {quest:8961} wants the {item:21987} ({npc:9017} in {area:1584}), the {item:21988} ({npc:9816} in Upper Blackrock Spire), the {item:21989} (the {npc:15206} in {zone:1451}) and a {item:22014} from the {faction:529}."] = "{npc:16033} 的灵魂站在 {area:254} 高处、{area:1583} 传送门前的平台上：在那里使用灵魂显形器。{quest:8961} 需要 {item:21987}（{area:1584} 的 {npc:9017}）、{item:21988}（黑石塔上层的 {npc:9816}）、{item:21989}（{zone:1451} 的 {npc:15206}），以及来自 {faction:529} 的一个 {item:22014}。",
}
